package org.mockito.internal.invocation;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Array;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.matcher.ArgumentMatcher;
import org.mockito.internal.matcher.Matcher;
import org.mockito.internal.matchers.CapturesArguments;
import org.mockito.internal.matchers.MatcherDecorator;
import org.mockito.internal.matchers.VarargMatcher;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.invocation.DescribedInvocation;
import org.mockito.invocation.Invocation;
import org.mockito.invocation.Location;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.mockito.internal.invocation.InvocationMatcher.captureArgumentsFrom;

public class InvocationMatcher_captureArgumentsFrom_TriageGen2Test {

    private Invocation invocation;
    private Method regularMethod;
    private Method varArgsMethod;

    // Mock interface for CapturesArguments
    public interface CapturesArguments {
        void captureFrom(Object arg);
    }

    // Concrete implementation for testing
    public static class TestCapturer implements CapturesArguments, ArgumentMatcher {
        public Object capturedValue;
        @Override
        public void captureFrom(Object arg) {
            this.capturedValue = arg;
        }
        @Override
        public boolean matches(Object argument) {
            return true;
        }
    }

    @Before
    public void setUp() throws NoSuchMethodException {
        invocation = mock(Invocation.class);
        regularMethod = this.getClass().getMethod("setUp");
        varArgsMethod = this.getClass().getMethod("setUp", String[].class);
    }

    @Test
    public void testCaptureArgumentsFrom_WithVarArgs_ThrowsException() throws NoSuchMethodException {
        when(invocation.getMethod()).thenReturn(varArgsMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{new String[]{"a", "b"}});

        // The implementation provided in the prompt throws UnsupportedOperationException if isVarArgs is true
        InvocationMatcher matcher = new InvocationMatcher(invocation, new ArrayList<>());

        assertThrows(UnsupportedOperationException.class, () -> {
            matcher.captureArgumentsFrom(invocation);
        });
    }

    @Test
    public void testCaptureArgumentsFrom_WithRegularMethod_CapturesArguments() throws NoSuchMethodException {
        when(invocation.getMethod()).thenReturn(regularMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"arg1", "arg2"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg1");
        when(invocation.getArgumentAt(1, Object.class)).thenReturn("arg2");

        TestCapturer capturer1 = new TestCapturer();
        TestCapturer capturer2 = new TestCapturer();
        List<Matcher> matchers = Arrays.asList(capturer1, capturer2);

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        assert org.junit.Assert.assertEquals("arg1", capturer1.capturedValue);
        assert org.junit.Assert.assertEquals("arg2", capturer2.capturedValue);
    }

    @Test
    public void testCaptureArgumentsFrom_WithRegularMethod_SkipsNonCapturingMatchers() throws NoSuchMethodException {
        when(invocation.getMethod()).thenReturn(regularMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"arg1"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg1");

        ArgumentMatcher nonCapturer = mock(ArgumentMatcher.class);
        TestCapturer capturer = new TestCapturer();
        List<Matcher> matchers = Arrays.asList(nonCapturer, capturer);

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        assert org.junit.Assert.assertEquals("arg1", capturer.capturedValue);
    }

    @Test
    public void testCaptureArgumentsFrom_WithEmptyMatchers_DoesNothing() throws NoSuchMethodException {
        when(invocation.getMethod()).thenReturn(regularMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{});

        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);
        // Should complete without exception
    }

    @Test
    public void testCaptureArgumentsFrom_WithNoCapturers_DoesNothing() throws NoSuchMethodException {
        when(invocation.getMethod()).thenReturn(regularMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"arg1"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg1");

        List<Matcher> matchers = Arrays.asList(mock(ArgumentMatcher.class));
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);
        // Should complete without exception
    }
}
